{"re_eligibility":0,"start_time":1706724000,"end_time":-1,"priority":2001302000,"min_seconds_since_last_trigger":-1,"timeout":-1,"delay":0,"id":"65ba9af878ae4a004bad45d3","trigger_condition":[{"type":"custom_event","data":{"event_name":"settings_cancel_membership"}}],"prefetch":true,"data":{"message":"<!DOCTYPE html>
<html>
  <head lang="en">
    <meta charset="UTF-8"/>
    <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover"/>
    <style>
      @font-face {
        font-family: "CentraBold";
        src: url("https://www.life360.com/wp-content/themes/life360-2021/fonts/CentraNo2-Bold.woff");
        font-weight: 700;
      }
      @font-face {
        font-family: "CentraBook";
        src: url("https://www.life360.com/wp-content/themes/life360-2021/fonts/CentraNo2-Book.woff");
        font-weight: 400;
      }
      body {
        pointer-events: none;
        background-color: #ffffff00;
        display: none;
      }
      body, .iam-container {
        margin: 0;
        padding: 0;
        height: 100vh;
        width: 100vw;
        position: fixed;
        left: 100vw;
        font-family: CentraBook, Arial, Helvetica, sans-serif;
      }
      h1, p {
        margin: 0;
        text-align: center;
      }
      h1 {
        font-family: CentraBold, Arial, Helvetica, sans-serif;
      }
      main {
        width: 100%;
        overflow-y: scroll;
      }
      .flex-column {
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
      }
      .iam-container {
        pointer-events: auto;
        background: #FFFFFF;
        left: 100vw;
        overflow-y: scroll;
        padding: 0;
        margin: 0;
      }
      .viewable {
        left: 0vw;
      }
      .hidden {
        left: 100vw;
      }
      .transition {
        transition-property: all;
        transition-duration: 0.3s;
        transition-timing-function: cubic-bezier(0.25, 0.1, 0.25, 1);
      }
      .top {
        width: 100%;
        height: 105px;
        position: absolute;
        border-bottom: 1px solid #E3E3E3;
        top: 0px;
        display: flex;
        flex-direction: row;
        align-items: flex-end;
        justify-content: center;
        background: #FFFFFF;
      }
      .cta-button {
        width: 75vw;
        padding: 17px 0px;
        background-color: #8652FF;
        border-radius: 50px;
        border: none;
        color: white;
        font-family: CentraBold, Arial, Helvetica, sans-serif;
        font-size: 17px;
        cursor: pointer;
      }
      .bottom {
        width: 100%;
        height: 175px;
        border-top: 1px solid rgb(228, 228, 228);
        box-shadow: 0px -5px 5px 0px rgba(0, 0, 0, 0.1);
        position: absolute;
        bottom: 0px;
        background: #FFFFFF;
      }
      #close-button {
        padding-bottom: 15px;
        position: absolute;
        left: 20px;
      }
      #benefits {
        margin: 0;
        align-self: flex-start;
        padding: 16px 0px 70px 22%;
      }
      #cancel-link {
        text-decoration: none;
        margin: 0;
        font-family: CentraBold, Arial, Helvetica, sans-serif;
        font-size: 17px;
        line-height: 22px;
        padding: 0px 0px 13px 0px;
        text-align: center;
        color: #FE736F;
      }
      @media screen and (max-height: 790px) {
        main {
          position: absolute;
          top: 105px;
          height: calc(100% - 280px);
        }
        main h1 {
          margin-top: 30px;
        }
        #benefits {
          margin: 0;
          align-self: flex-start;
          padding: 16px 0px 30px 22%;
        }
      }
    </style>
  </head>

  <body class="transition">
    <!-- Message element -->
    <div class="iam-container transition flex-column" >
      <!-- Close button and header (top) -->
      <div class="top">
        <img id="close-button" onclick="closeMessage()" src="https://braze-images.com/appboy/communication/assets/image_assets/images/65b15f93d75e1a004b8bf1d7/original.png?1706123155" width="24px"/>
        <p style="padding: 0px 0px 16px 0px; font-size: 17px; line-height: 22px;">Membership Management</p>
      </div>
      <main>
        <div class="flex-column">
          <!-- Header text -->
          <h1 style="font-size: 25px; line-height: 30px; padding: 0px 11% 0px 11%;">We’d love for you to stay. Save <span style="background-color: #fff550;">$79</span> today!</h1>
          <!-- Hero image -->
          <img style="width: 50%; margin: 0 auto; padding: 11px 0px 0px 0px;" src="https://braze-images.com/appboy/communication/assets/image_assets/images/65b15f934e7266004cd970a3/original.png?1706123155" alt="Gold membership card">
          <!-- Body text -->
          <p style="text-align: left; padding: 30px 11% 0px 11%; font-size: 17px; line-height: 22px;">Switch to an annual membership and enjoy the same benefits with a 44% discount. Don’t lose access to our top safety features:</p>
          <!-- Bulleted list -->
          <ul id="benefits">
            <li>24/7 Emergency Dispatch</li>
            <li>Individual Driver Reports</li>
            <li>Roadside Assistance</li>
            <li>Unlimited Place Alerts</li>
            <li>30-Day Location History</li>
          </ul>
        </div>
      </main>
      <!-- Bottom section -->
      <div class="bottom flex-column">
        <h1 style="font-size: 20px; line-height: 25px; padding: 0px 11% 0px 11%;">Just <span style="color: #494949; text-decoration: line-through;">$179.88</span> $99.99 per year</h1>
        <!-- CTA button -->
        <a onclick="appboyBridge.logClick('1');" href="life360://goldannual-iap">
          <button class="cta-button" style="margin: 14px 0px 16px 0px;">
            <span>Switch to Annual</span>
          </button>
        </a>
        <a onclick="appboyBridge.logClick('cancel_membership');" id="cancel-link" href="https://play.google.com/store/account/subscriptions">Cancel my membership</a>
      </div>
    </div>
    <script>
      // Establish element variables
      var iamContainer = document.querySelector('.iam-container');
      var body = document.querySelector('body');
      var isSafariOrUiWebview = /(iPhone|iPod|iPad).*AppleWebKit/i.test(navigator.userAgent);

      // Trigger slide-up animation
      window.onload = function() {
        // Wait a moment for the IAM to load from Braze, then begin animations
        setTimeout(function() {
          body.style.display = "initial"
        }, 100);
        setTimeout(function() {
          iamContainer.classList.add('viewable');
        }, 400);
        if (isSafariOrUiWebview) {
          document.getElementById('cancel-link').href = 'https://apps.apple.com/account/subscriptions';
        }
      }

      // Trigger slide-down animation
      function closeMessage() {
        // Begin animations
        iamContainer.classList.remove('viewable');
        iamContainer.classList.add('hidden');
        // After animations, log exit for metrics and close message
        setTimeout(function() {
          appboyBridge.logClick('exit');
          appboyBridge.closeMessage();
        }, 300);
      }
    </script>
  </body>
</html>","type":"HTML","message_close":"SWIPE","asset_urls":["https://braze-images.com/appboy/communication/assets/image_assets/images/65b15f93d75e1a004b8bf1d7/original.png?1706123155","https://braze-images.com/appboy/communication/assets/image_assets/images/65b15f934e7266004cd970a3/original.png?1706123155"],"trusted":false,"trigger_id":"NjViYTlhZjg3OGFlNGEwMDRiYWQ0NWQzXyRfbXY9NjViYTlhZjk3OGFlNGEwMDRiYWQ0NWRkJnBpPWNtcA=="},"type":"inapp"}
